<?php
require __DIR__.'/../includes/bootstrap.php'; require_login(); $u = current_user();
$f = in_array($_GET['status'] ?? '', ['submitted','in_review','changes_requested','approved','rejected'], true) ? $_GET['status'] : '';
$page = ob_page_param(); $per = 10; $rows = []; $total = 0; $summary = ['all'=>0,'pending'=>0,'approved'=>0,'attention'=>0];
try {
  $s = db()->prepare("SELECT COUNT(*) n, COALESCE(SUM(status IN ('submitted','in_review')),0) p, COALESCE(SUM(status='approved'),0) a, COALESCE(SUM(status IN ('changes_requested','rejected')),0) x FROM submissions WHERE contributor_id=?"); $s->execute([$u['id']]); $c = $s->fetch();
  $summary = ['all'=>(int)$c['n'],'pending'=>(int)$c['p'],'approved'=>(int)$c['a'],'attention'=>(int)$c['x']];
  $where = 's.contributor_id=?'; $args = [$u['id']]; if ($f !== '') { $where .= ' AND s.status=?'; $args[] = $f; }
  $s = db()->prepare("SELECT COUNT(*) FROM submissions s WHERE $where"); $s->execute($args); $total = (int)$s->fetchColumn(); $off = ($page - 1) * $per;
  $s = db()->prepare("SELECT s.*,b.title bounty_title,b.reward_xlm,b.status bounty_status,cu.full_name creator,p.status pay_status FROM submissions s JOIN bounties b ON b.id=s.bounty_id JOIN users cu ON cu.id=b.creator_id LEFT JOIN payments p ON p.submission_id=s.id WHERE $where ORDER BY s.created_at DESC LIMIT $per OFFSET $off"); $s->execute($args); $rows = $s->fetchAll();
} catch (Throwable $e) { error_log($e->getMessage()); }
$pageTitle = 'My submissions'; require __DIR__.'/../includes/header.php';
echo ob_page_head('My submissions', 'Track your submitted work, reviewer decisions and feedback.', '<a class="ob-btn" href="/OpenBounty/bounties/">'.ob_icon('compass', 16).'Find a bounty</a>');
$stage = function (array $r): int { if ($r['pay_status'] === 'verified') return 4; if ($r['status'] === 'approved') return 3; if (in_array($r['status'], ['rejected','changes_requested'], true)) return 3; if ($r['status'] === 'in_review') return 2; return 1; };
?>
<div class="ob-grid ob-g4" style="margin-bottom:18px"><div class="ob-card ob-stat"><span>Total</span><strong><?= $summary['all'] ?></strong></div><div class="ob-card ob-stat"><span>Awaiting review</span><strong><?= $summary['pending'] ?></strong></div><div class="ob-card ob-stat"><span>Approved</span><strong><?= $summary['approved'] ?></strong></div><div class="ob-card ob-stat"><span>Needs attention</span><strong><?= $summary['attention'] ?></strong></div></div>
<div class="ob-chips" style="margin-bottom:16px"><a class="ob-chip<?= $f===''?' on':'' ?>" href="?">All</a><?php foreach (['submitted'=>'Submitted','in_review'=>'In review','changes_requested'=>'Changes requested','approved'=>'Approved','rejected'=>'Rejected'] as $k => $l): ?><a class="ob-chip<?= $f===$k?' on':'' ?>" href="?status=<?= e($k) ?>"><?= e($l) ?></a><?php endforeach; ?></div>
<?php if (!$rows): ?><?= $summary['all'] === 0 ? ob_empty('upload', 'No submissions yet', 'Browse the marketplace and submit your first contribution.', '<a class="ob-btn" href="/OpenBounty/bounties/">Browse bounties</a>') : ob_empty('inbox', 'No submissions in this view', '', '<a class="ob-btn ghost" href="?">Show all</a>') ?>
<?php else: ?><div class="ob-stack">
<?php foreach ($rows as $r): $st = $stage($r); $bad = in_array($r['status'], ['rejected','changes_requested'], true); ?>
<article class="ob-card"><div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap"><div><h3><a href="/OpenBounty/bounties/view.php?id=<?= (int)$r['bounty_id'] ?>" style="color:var(--text)"><?= e($r['bounty_title']) ?></a></h3><div class="ob-muted" style="font-size:12.5px">by <?= e($r['creator']) ?> · submitted <?= e(ob_date($r['created_at'])) ?></div></div><div style="text-align:right"><div class="ob-reward"><?= e(xlm($r['reward_xlm'])) ?> <small>XLM</small></div><?= ob_badge((string)$r['status']) ?></div></div>
<ol style="list-style:none;display:flex;gap:6px;padding:0;margin:16px 0 4px;font-size:12px;flex-wrap:wrap"><?php foreach ([1=>'Submitted',2=>'In review',3=>$bad ? ob_label((string)$r['status']) : 'Approved',4=>'Payment verified'] as $n => $l): ?><li class="ob-badge <?= $st >= $n ? ($n === 3 && $bad ? 'amber' : 'purple') : 'gray' ?>"><?= e($l) ?></li><?php endforeach; ?></ol>
<details class="ob-det" style="margin-top:12px"><summary>View details</summary><dl class="ob-kv"><dt>Evidence</dt><dd><a href="<?= e($r['submission_url']) ?>" target="_blank" rel="noopener noreferrer"><?= e($r['submission_url']) ?></a></dd><?php if ($r['notes']): ?><dt>Your notes</dt><dd class="ob-prose"><?= e($r['notes']) ?></dd><?php endif; ?><dt>Reviewed</dt><dd><?= $r['reviewed_at'] ? e(ob_date($r['reviewed_at'], 'M j, Y g:i A')) : 'Not yet' ?></dd><dt>Creator feedback</dt><dd class="ob-prose"><?= $r['review_notes'] ? e($r['review_notes']) : '<span class="ob-muted">No feedback yet</span>' ?></dd><dt>Payment</dt><dd><?= $r['pay_status'] ? ob_badge((string)$r['pay_status']) : '<span class="ob-muted">No payment recorded</span>' ?></dd></dl></details></article>
<?php endforeach; ?></div><?= ob_pager($total, $per, $page, ['status'=>$f]) ?><?php endif; ?>
<?php require __DIR__.'/../includes/footer.php'; ?>
